mapper.select:
SELECT user_id, balance, created_at, updated_at
FROM user_coin_balances
WHERE user_id = #{userId}

mapper.update:
UPDATE user_coin_balances
SET balance = balance + #{amount}
WHERE user_id = #{userId}

UPDATE user_coin_balances
SET balance = balance - #{amount}
WHERE user_id = #{userId}
  AND balance >= #{amount}

mapper.select:
SELECT COUNT(1)
FROM coin_transactions
WHERE user_id = #{userId}
